#include <bits/stdc++.h>
using namespace std;

// greater[i][c]: how many of the first i characters of s are strictly greater than c.
vector<array<int, 26>> greaterCounts(const string &s) {
    vector<array<int, 26>> rows(s.size() + 1);
    array<int, 26> counts{};
    rows[0].fill(0);
    for (size_t i = 0; i < s.size(); i++) {
        counts[s[i] - 'a']++;
        int total = 0;
        for (int c = 25; c >= 0; c--) {
            rows[i + 1][c] = total;
            total += counts[c];
        }
    }
    return rows;
}

int main() {
    string a, b;
    cin >> a >> b;
    int n = a.size(), m = b.size();
    auto ga = greaterCounts(a), gb = greaterCounts(b);
    // previous[j]: fewest inversions using a[0..i) and b[0..j).
    vector<long long> previous(m + 1, 0), current(m + 1, 0);
    for (int j = 1; j <= m; j++) previous[j] = previous[j - 1] + gb[j - 1][b[j - 1] - 'a'];
    for (int i = 1; i <= n; i++) {
        int ca = a[i - 1] - 'a';
        current[0] = previous[0] + ga[i - 1][ca];
        for (int j = 1; j <= m; j++) {
            int cb = b[j - 1] - 'a';
            current[j] = min(previous[j] + ga[i - 1][ca] + gb[j][ca], current[j - 1] + ga[i][cb] + gb[j - 1][cb]);
        }
        swap(previous, current);
    }
    cout << previous[m] << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    // greater[i][c]: how many of the first i characters of s are strictly greater than c.
    static int[][] greaterCounts(String s) {
        int[][] rows = new int[s.length() + 1][26];
        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) {
            counts[s.charAt(i) - 'a']++;
            int total = 0;
            for (int c = 25; c >= 0; c--) {
                rows[i + 1][c] = total;
                total += counts[c];
            }
        }
        return rows;
    }

    public static void main(String[] args) throws IOException {
        String a = next(), b = next();
        int n = a.length(), m = b.length();
        int[][] ga = greaterCounts(a), gb = greaterCounts(b);
        // previous[j]: fewest inversions using a[0..i) and b[0..j).
        long[] previous = new long[m + 1], current = new long[m + 1];
        for (int j = 1; j <= m; j++) previous[j] = previous[j - 1] + gb[j - 1][b.charAt(j - 1) - 'a'];
        for (int i = 1; i <= n; i++) {
            int ca = a.charAt(i - 1) - 'a';
            current[0] = previous[0] + ga[i - 1][ca];
            for (int j = 1; j <= m; j++) {
                int cb = b.charAt(j - 1) - 'a';
                current[j] = Math.min(previous[j] + ga[i - 1][ca] + gb[j][ca], current[j - 1] + ga[i][cb] + gb[j - 1][cb]);
            }
            long[] t = previous;
            previous = current;
            current = t;
        }
        System.out.println(previous[m]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

// greaterCounts(s)[i][c]: how many of the first i characters of s are strictly greater than c.
func greaterCounts(s []byte) [][26]int {
	rows := make([][26]int, len(s)+1)
	var counts [26]int
	for i, ch := range s {
		counts[ch-'a']++
		total := 0
		for c := 25; c >= 0; c-- {
			rows[i+1][c] = total
			total += counts[c]
		}
	}
	return rows
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	a, b := token(), token()
	n, m := len(a), len(b)
	ga, gb := greaterCounts(a), greaterCounts(b)
	// previous[j]: fewest inversions using a[0..i) and b[0..j).
	previous, current := make([]int, m+1), make([]int, m+1)
	for j := 1; j <= m; j++ {
		previous[j] = previous[j-1] + gb[j-1][b[j-1]-'a']
	}
	for i := 1; i <= n; i++ {
		ca := a[i-1] - 'a'
		current[0] = previous[0] + ga[i-1][ca]
		for j := 1; j <= m; j++ {
			cb := b[j-1] - 'a'
			current[j] = min(previous[j]+ga[i-1][ca]+gb[j][ca], current[j-1]+ga[i][cb]+gb[j-1][cb])
		}
		previous, current = current, previous
	}
	fmt.Println(previous[m])
}
